# Q4c: reviewer fixes (turn 3 of the Q4 re-review): differential N-vs-S comparison with J=1-0 literature data, separate-density class, physical (single-cloud) quantities, CS discriminator, scope of SO/IR-pumping, consistency of report.
# Idempotent: removes entries tagged 'Q4c:' and the superseded Q4/Q4b entries; patches interpretation/caveats. Backup: out/report.backup.q4c.json
import json,shutil,os
P='/output/report.json'
if not os.path.exists('/workspace/out/report.backup.q4c.json'): shutil.copy(P,'/workspace/out/report.backup.q4c.json')
r=json.load(open(P))
r['recipe']=[x for x in r['recipe'] if not x.get('description','').startswith('Q4c:')]
SUPER=('Q4: H13CN(4-3)/HCN(4-3) at a common','Q4: RADEX test of what the H13CN limit','Q4b: Why is HCN/HCO+ 3-2 low at S','Q4b: Literature benchmarks','Q4b: Q4 summary')
r['results']=[x for x in r['results'] if not x['quantity'].startswith('Q4c:') and not x['quantity'].startswith(SUPER)]
A=lambda n,v,u=None:{'name':n,'value':v,'unit':u}
def R(q,v,u,c,e,t,a,un=None): return {'quantity':'Q4c: '+q,'target':t,'value':v,'uncertainty':un,'unit':u,'assumptions':a,'confidence':c,'evidence':e}
# --- patches of kept entries
for x in r['results']:
    if x['quantity'].startswith('Q4b: Beam-filling / dilution'):
        i=x['value'].find('Per-cloud column:')
        if i>0: x['value']=x['value'][:i]+"Per-cloud column, N(H2), Sigma, path length and the clumping statement of this entry are SUPERSEDED by 'Q4c: physical quantities with a single-cloud line width' (dv=50 km/s; the earlier 'N(H2)=2.5e24-2.5e25 = 4e3-4e4 Msun/pc2' conversion was wrong: 1e24 cm-2 of H2 (with He) is 2.2e4 Msun/pc2)."
    if x['quantity'].startswith('Q4: SO(5-4'):
        j=x['value'].find('So SO shows no warm/hot')
        if j>0: x['value']=x['value'][:j]+"Scope: this is a central-beam (9.4x6.3\", N+S+Bridge blended) average of the ratio, convolved to a common beam; it is NOT a nuclear measurement. A cold SO Trot from two lines of one species does not exclude shocked gas that is compact (see 'Q4c: SO scope'); the stronger shock constraint is CH3OH/HCO+ at 0.95\" (nuclei <0.013/<0.017 vs Bridge 0.052)."
    if x['quantity'].startswith('Q4: CH3OH/HCO+ and other shock'):
        x['value']=x['value'].replace('Band 7 (4.1x2.7"): CS 7-6/HCO+ 4-3 N 0.081+-0.012, S 0.047+-0.015','Band 7 (4.1x2.7", peak-pixel values, N and S only partly separated by this beam and therefore SUPERSEDED by the deblended CS entry Q4c): CS 7-6/HCO+ 4-3 N 0.081+-0.012, S 0.047+-0.015')
    if x['quantity'].startswith('Q4: HCN v2=1f'):
        x['value']=x['value'].replace('No sign of IR pumping at N or S at 0.24-6\\"; S limit at 0.24\\" is the weakest (<8%).','No vibrational HCN detected at N or S at 0.24-6\\"; S limit at 0.24\\" is the weakest (<8%). This does NOT exclude IR pumping at the Tvib~200-300 K of other CON/obscured nuclei (see Q4c: HCN v2=1f).')
